    public function options():array{$c=$this->settings->config();$manual=(new ManualMethods($this->db))->active();return ['mode'=>$c['mode'],'paypalRate'=>$c['paypalEnabled']?$c['paypalRate']:null,'manualOptions'=>$manual,'manualMethods'=>array_column($manual,'id'),'providers'=>$c['mode']==='LIVE'?array_merge($c['vnpayEnabled']?array_merge(['VNPAY','VNPAY_QR'],$c['vnpayCardEnabled']?['VNPAY_CARD']:[]):[],SepaySettings::ready($c)?['SEPAY']:[],SepayCardSettings::ready($c)?['SEPAY_CARD']:[],PaypalSettings::ready($c)?['PAYPAL']:[]):[]];}
    public function checkout(array $in,string $ip,bool $test=false,?array $context=null):array
    {
        if(array_diff(array_keys($in),['code','accessKey','email','provider'])||!is_string($in['code']??null)||!preg_match('/^J[GMCBH][A-F0-9]{10}$/D',$in['code'])||!in_array($in['provider']??null,['VNPAY','VNPAY_QR','VNPAY_CARD'],true)||array_key_exists('accessKey',$in)&&(!is_string($in['accessKey'])||!preg_match('/^[a-f0-9]{64}$/D',$in['accessKey']))||array_key_exists('email',$in)&&(!is_string($in['email'])||strlen($in['email'])>200||!filter_var($in['email'],FILTER_VALIDATE_EMAIL)))throw new HttpError(400,'Kiểm tra mã đơn, khóa/email và cổng thanh toán.');if($context!==null&&($test||!str_starts_with($in['code'],'JC')))throw new HttpError(400,'Chỉ thanh toán giỏ CTV LIVE.');if(!$test&&$context===null&&!isset($in['accessKey'])&&!isset($in['email']))throw new HttpError(400,'Nhập khóa hoặc email tra cứu.');if($test&&(str_starts_with($in['code'],'JB')||str_starts_with($in['code'],'JH')))throw new HttpError(400,'TEST dùng vé đơn hoặc giỏ vé web.');
        return $this->tx(function()use($in,$ip,$test,$context){$c=$this->settings->config();if($c['mode']!==($test?'TEST':'LIVE')||!$c['vnpayEnabled']||empty($c['vnpayEncrypted'])||$in['provider']==='VNPAY_CARD'&&!$c['vnpayCardEnabled'])throw new HttpError(400,'Cổng chưa bật hoặc đang ở môi trường khác.');$base=$this->settings->base();if(!$test&&!str_starts_with($base,'https://'))throw new HttpError(503,'Thanh toán LIVE cần HTTPS.');if($context!==null)(new PaymentTargets($this->db))->authorizeContext($in,$context);elseif(!$test)(new PaymentTargets($this->db))->authorizeCode($in);$s=(new PaymentTargets($this->db))->state($in['code'],$context);$config=['tmnCode'=>$c['tmnCode'],'secret'=>$c['vnpayEncrypted'],'card'=>$in['provider']==='VNPAY_CARD','qr'=>$in['provider']==='VNPAY_QR'];if(isset($s['hotel']))$config['hotelId']=$s['hotel']['row']['id'];elseif($s['bundle'])$config['bundleId']=$s['bundle']['id'];elseif($s['cart'])$config+=['cartId'=>$s['cart']['id'],'cartOrders'=>array_map(fn($o)=>['id'=>$o['id'],'amount'=>json_decode($o['snapshot'],true,512,JSON_THROW_ON_ERROR)['total']],$s['orders']),'channel'=>$s['cart']['channel'],'partnerId'=>$s['cart']['partner_id'],'counterId'=>$s['cart']['counter_id']];$orderId=$s['orders'][0]['id']??null;$q=$this->query("SELECT * FROM jingo_gateway_attempts WHERE provider='VNPAY' AND mode=? AND config_version=? AND amount=? AND status='PENDING' AND expires_at>UTC_TIMESTAMP(6) ORDER BY created_at DESC,id DESC",[$c['mode'],$c['version'],$s['amount']]);$attempt=null;while($r=$q->fetch(PDO::FETCH_ASSOC))if($r['order_id']===$orderId&&json_decode($r['config'],true,512,JSON_THROW_ON_ERROR)===$config){$attempt=$r;break;}if(!$attempt){$id='JMP'.strtoupper(bin2hex(random_bytes(12)));$this->query("INSERT INTO jingo_gateway_attempts(id,order_id,provider,mode,amount,config_version,config,expires_at) VALUES (?,?,'VNPAY',?,?,?,?,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 15 MINUTE))",[$id,$orderId,$c['mode'],$s['amount'],$c['version'],json_encode($config,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$attempt=$this->query('SELECT * FROM jingo_gateway_attempts WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);}$params=['vnp_Version'=>'2.1.0','vnp_Command'=>'pay','vnp_TmnCode'=>$config['tmnCode'],'vnp_Amount'=>(string)($s['amount']*100),'vnp_CurrCode'=>'VND','vnp_TxnRef'=>$attempt['id'],'vnp_OrderInfo'=>'Thanh toan '.$in['code'],'vnp_OrderType'=>'other','vnp_Locale'=>$s['locale']==='en'?'en':'vn','vnp_ReturnUrl'=>$base.'/api/v1/payments/vnpay/return','vnp_IpAddr'=>filter_var($ip,FILTER_VALIDATE_IP)?$ip:'127.0.0.1','vnp_CreateDate'=>PaymentProtocol::vnTime($attempt['created_at']),'vnp_ExpireDate'=>PaymentProtocol::vnTime($attempt['expires_at'])];if($config['card'])$params['vnp_BankCode']='INTCARD';elseif($config['qr'])$params['vnp_BankCode']='VNPAYQR';$url=($test?'https://sandbox.vnpayment.vn/paymentv2/vpcpay.html':'https://pay.vnpay.vn/vpcpay.html').'?'.PaymentProtocol::canonical($params).'&vnp_SecureHash='.PaymentProtocol::sign($params,(new SecretCipher(OrderMail::directory()))->decrypt($config['secret']));return ['id'=>$attempt['id'],'provider'=>'VNPAY','mode'=>$c['mode'],'amount'=>$s['amount'],'expiresAt'=>$attempt['expires_at'],'url'=>$url];});
    }
    public function returnPath(?array $query):string
    {
        $id=$query['vnp_TxnRef']??'';if(is_string($id)&&preg_match('/^JMP[A-F0-9]{24}$/D',$id)){$r=$this->query("SELECT config FROM jingo_gateway_attempts WHERE id=? AND provider='VNPAY'",[$id])->fetchColumn();if($r)return PaymentTargets::returnPath(json_decode($r,true,512,JSON_THROW_ON_ERROR));}return '/tra-cuu?gateway=return';
    }
    public function ipn(?array $q):array
    {
        if($q===null||count($q)>40||array_filter($q,fn($v)=>!is_string($v)||strlen($v)>2000))return ['RspCode'=>'97','Message'=>'Invalid signature'];if(!preg_match('/^JMP[A-F0-9]{24}$/D',$q['vnp_TxnRef']??''))return ['RspCode'=>'01','Message'=>'Order not found'];$a=$this->query("SELECT * FROM jingo_gateway_attempts WHERE id=? AND provider='VNPAY'",[$q['vnp_TxnRef']])->fetch(PDO::FETCH_ASSOC);if(!$a)return ['RspCode'=>'01','Message'=>'Order not found'];$config=json_decode($a['config'],true,512,JSON_THROW_ON_ERROR);if(!PaymentProtocol::verify($q,(new SecretCipher(OrderMail::directory()))->decrypt($config['secret']))||($q['vnp_TmnCode']??'')!==$config['tmnCode'])return ['RspCode'=>'97','Message'=>'Invalid signature'];if(!preg_match('/^[0-9]{1,15}$/D',$q['vnp_Amount']??'')||(int)$q['vnp_Amount']%100!==0||(int)$q['vnp_Amount']>1500000000000)return ['RspCode'=>'04','Message'=>'Invalid amount'];$amount=intdiv((int)$q['vnp_Amount'],100);if($amount!==(int)$a['amount']){$this->settle($a,'MISMATCH:'.$a['id'].':'.$q['vnp_Amount'],$amount,hash('sha256',json_encode(['attempt'=>$a['id'],'amount'=>(int)$q['vnp_Amount']])),'Số tiền VNPAY không khớp');return ['RspCode'=>'04','Message'=>'Invalid amount'];}if(($q['vnp_ResponseCode']??'')!=='00'||($q['vnp_TransactionStatus']??'')!=='00')return $this->tx(function()use($q,$a){$id='VNPAY:'.$a['mode'].':FAIL:'.$a['id'];$this->query("INSERT INTO jingo_gateway_events(id,attempt_id,order_id,provider,mode,amount,status,reason,fingerprint) VALUES (?,?,?,'VNPAY',?,0,'FAILED',?,?) ON DUPLICATE KEY UPDATE id=id",[$id,$a['id'],$a['order_id'],$a['mode'],'VNPAY không thành công: '.substr($q['vnp_ResponseCode']??'',0,10).' / '.substr($q['vnp_TransactionStatus']??'',0,10),hash('sha256',PaymentProtocol::canonical($q))]);$this->query("UPDATE jingo_gateway_attempts SET status='FAILED' WHERE id=? AND status='PENDING'",[$a['id']]);return ['RspCode'=>'00','Message'=>'Non-success notification acknowledged'];});if(!preg_match('/^[1-9][0-9]{0,29}$/D',$q['vnp_TransactionNo']??''))return ['RspCode'=>'99','Message'=>'Invalid transaction'];try{$r=$this->settle($a,$q['vnp_TransactionNo'],$amount,hash('sha256',json_encode(['attempt'=>$a['id'],'transaction'=>$q['vnp_TransactionNo'],'amount'=>(int)$q['vnp_Amount']])));return ['RspCode'=>$r['duplicate']?'02':'00','Message'=>$r['duplicate']?'Already confirmed':'Confirmed'];}catch(HttpError $e){if($e->status===409)return ['RspCode'=>'99','Message'=>'Transaction conflict'];throw $e;}
    }
    private function settle(array $original,string $external,int $amount,string $fingerprint,string $reason=''):array
    {
        return $this->tx(function()use($original,$external,$amount,$fingerprint,$reason){$id='VNPAY:'.$original['mode'].':'.$external;$prior=$this->query('SELECT status,fingerprint FROM jingo_gateway_events WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);if($prior){if(!hash_equals($prior['fingerprint'],$fingerprint))throw new HttpError(409,'Giao dịch đã nhận với dữ liệu khác.');return ['duplicate'=>true,'status'=>$prior['status']];}$a=$this->query('SELECT * FROM jingo_gateway_attempts WHERE id=? FOR UPDATE',[$original['id']])->fetch(PDO::FETCH_ASSOC);$config=json_decode($a['config'],true,512,JSON_THROW_ON_ERROR);$this->query("INSERT INTO jingo_gateway_events(id,attempt_id,order_id,provider,mode,amount,status,reason,fingerprint) VALUES (?,?,?,'VNPAY',?,?,'REVIEW','Đang xử lý',?)",[$id,$a['id'],$a['order_id'],$a['mode'],$amount,$fingerprint]);$s=null;try{if(isset($config['hotelId'])){$code=$this->query('SELECT code FROM jingo_stay_bookings WHERE id=?',[$config['hotelId']])->fetchColumn();if(!$code)throw new HttpError(409,'Không tìm thấy đơn phòng.');$s=(new PaymentTargets($this->db))->state($code,PaymentTargets::context($config));}elseif(isset($config['bundleId'])){$b=$this->query('SELECT code FROM jingo_checkout_bundles WHERE id=?',[$config['bundleId']])->fetchColumn();if(!$b)throw new HttpError(409,'Mã tổng không còn hợp lệ.');$s=(new PaymentTargets($this->db))->state($b,PaymentTargets::context($config));}elseif(isset($config['cartId'])){$code=$this->query('SELECT code FROM jingo_carts WHERE id=?',[$config['cartId']])->fetchColumn();if(!$code)throw new HttpError(409,'Giỏ không còn hợp lệ.');$s=(new PaymentTargets($this->db))->state($code,PaymentTargets::context($config));$currentTargets=array_map(fn($o)=>['id'=>$o['id'],'amount'=>json_decode($o['snapshot'],true,512,JSON_THROW_ON_ERROR)['total']],$s['orders']);if($currentTargets!==$config['cartOrders'])$reason='Thành phần giỏ đã thay đổi.';}else{$code=$this->query('SELECT code FROM jingo_orders WHERE id=?',[$a['order_id']])->fetchColumn();if(!$code)throw new HttpError(409,'Đơn không còn hợp lệ.');$s=(new PaymentTargets($this->db))->state($code,PaymentTargets::context($config));}}catch(HttpError $e){$reason=$reason?:$e->getMessage();}if(!$s||$s['amount']!==$amount||(int)$a['amount']!==$amount)$reason=$reason?:'Số tiền không khớp.';if(strtotime($a['expires_at'].' UTC')<=time())$reason='Yêu cầu đã hết hạn; cần đối soát thủ công.';$current=$this->settings->config();if($current['mode']!==$a['mode']||!$current['vnpayEnabled'])$reason='Cổng đã tắt hoặc đổi môi trường.';elseif(($current['vnpayEncrypted']??null)!==$config['secret']||$current['tmnCode']!==$config['tmnCode'])$reason='Tài khoản hoặc khóa VNPAY đã thay đổi.';elseif(!empty($config['card'])&&!$current['vnpayCardEnabled'])$reason='Thẻ VNPAY đã tắt.';if($this->query('SELECT reference_hash FROM jingo_payment_references WHERE reference_hash=?',[hash('sha256',$id)])->fetchColumn())$reason='Giao dịch đã có trong sổ thu.';$status=$reason!==''?'REVIEW':($a['mode']==='TEST'?'TEST':'PAID');if($status==='PAID')(new PaymentTargets($this->db))->credit($s,$id,'VNPAY');if(isset($config['hotelId'])&&$this->query('SELECT id FROM jingo_stay_bookings WHERE id=?',[$config['hotelId']])->fetchColumn())$this->query('INSERT INTO jingo_stay_payment_events(event_id,booking_id) VALUES (?,?)',[$id,$config['hotelId']]);$this->query('UPDATE jingo_gateway_events SET status=?,reason=? WHERE id=?',[$status,$reason,$id]);$this->query("UPDATE jingo_gateway_attempts SET status=? WHERE id=? AND status<>'PAID'",[$status,$a['id']]);return ['duplicate'=>false,'status'=>$status];});
    }
    private function read(callable $fn):array{$this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{$r=$fn();$this->db->commit();return $r;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    public function events(array $in):array
    {
        if(array_diff(array_keys($in),['q','status','page'])||isset($in['q'])&&!is_string($in['q'])||array_key_exists('q',$in)&&$in['q']===null||mb_strlen($in['q']??'')>100||isset($in['status'])&&!in_array($in['status'],['ALL','PAID','TEST','REVIEW','FAILED'],true)||array_key_exists('status',$in)&&$in['status']===null||array_key_exists('page',$in)&&!is_int($in['page'])&&!is_string($in['page'])||!preg_match('/^[1-9][0-9]{0,5}$/D',(string)($in['page']??'1')))throw new HttpError(400,'Bộ lọc nhật ký không hợp lệ.');return $this->read(function()use($in){$args=[];$where=[];if(($in['status']??'ALL')!=='ALL'){$where[]='e.status=?';$args[]=$in['status'];}if(trim($in['q']??'')!==''){$where[]="LOCATE(LOWER(?),LOWER(CONCAT_WS(' ',e.id,e.attempt_id,o.code,c.code,b.code,h.code,r.target_code,original.code,ride.code)))>0";$args[]=trim($in['q']);}$sql=' FROM jingo_gateway_events e LEFT JOIN jingo_gateway_attempts a ON a.id=e.attempt_id LEFT JOIN jingo_orders o ON o.id=e.order_id LEFT JOIN jingo_cart_orders cm ON cm.order_id=e.order_id LEFT JOIN jingo_carts c ON c.id=COALESCE(JSON_UNQUOTE(JSON_EXTRACT(a.config,\'$.cartId\')),cm.cart_id) LEFT JOIN jingo_checkout_bundles b ON b.id=JSON_UNQUOTE(JSON_EXTRACT(a.config,\'$.bundleId\')) LEFT JOIN jingo_stay_bookings h ON h.id=JSON_UNQUOTE(JSON_EXTRACT(a.config,\'$.hotelId\')) LEFT JOIN jingo_ride_payment_events ride_event ON ride_event.event_id=e.id LEFT JOIN jingo_ride_bookings ride ON ride.id=ride_event.ride_id LEFT JOIN jingo_gateway_resolutions r ON r.event_id=e.id LEFT JOIN jingo_orders original ON original.id=r.original_order_id LEFT JOIN jingo_carts resolved_cart ON resolved_cart.code=r.target_code LEFT JOIN jingo_checkout_bundles resolved_bundle ON resolved_bundle.code=r.target_code LEFT JOIN jingo_stay_bookings resolved_hotel ON resolved_hotel.code=r.target_code'.($where?' WHERE '.implode(' AND ',$where):'');$total=(int)$this->query('SELECT COUNT(*)'.$sql,$args)->fetchColumn();$page=min((int)($in['page']??1),max(1,(int)ceil($total/25)));$rows=$this->query('SELECT JSON_UNQUOTE(JSON_EXTRACT(a.config,\'$.channel\')) AS channel,JSON_UNQUOTE(JSON_EXTRACT(a.config,\'$.usdCents\')) AS usd_cents,JSON_UNQUOTE(JSON_EXTRACT(a.config,\'$.paypalRate\')) AS exchange_rate,e.id,e.attempt_id,e.provider,e.mode,e.amount,e.status,e.reason,e.created_at,COALESCE(o.code,ride.code) AS order_code,ride.id AS ride_id,COALESCE(resolved_cart.code,c.code) AS cart_code,COALESCE(resolved_bundle.code,b.code) AS bundle_code,COALESCE(resolved_hotel.code,h.code) AS hotel_code,r.target_code AS resolved_target_code,r.admin_id AS resolved_by,r.note AS resolution_note,r.original_reason,r.created_at AS resolved_at,original.code AS original_order_code'.$sql.' ORDER BY e.created_at DESC,e.id DESC LIMIT 25 OFFSET '.(($page-1)*25),$args)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['amount']=(int)$r['amount'];foreach(['usd_cents','exchange_rate'] as $key)$r[$key]=$r[$key]===null?null:(int)$r[$key];}unset($r);return ['data'=>$rows,'total'=>$total,'page'=>$page,'pageSize'=>25];});
    }
